<?php

namespace Bga\Games\RegroupChickenArmy\StateHandlers;

use Bga\Games\RegroupChickenArmy\Game;
use Bga\Games\RegroupChickenArmy\Components\Resources;
use Bga\Games\RegroupChickenArmy\Components\Players;
use BgaVisibleSystemException;

class AtkPhaseStateHandler implements StateHandlerInterface
{
    /* AUTOGENERATED_HANDLE_START - DO NOT REMOVE THIS COMMENT */
    public static function handle(Game $game, string $action, ...$args): void
    {
        switch ($action) {

            default:
                throw new BgaVisibleSystemException("Invalid action: $action");
        }
    }
    /* AUTOGENERATED_HANDLE_END - DO NOT REMOVE THIS COMMENT */

    /**
     * Calculate damage that all leaders would inflict to each other
     */
    private static function calculateDamageForAllLeaders(Game $game): array
    {
        $game->trace("Calculating damage for all leaders");

        // Get all remaining players
        $remainingPlayers = Players::getRemainingPlayersInOrder($game);

        // Get all resources at once
        $allResources = Resources::getAllResources($game);

        $damageResults = [];

        // For each attacker
        foreach ($remainingPlayers as $attackerId => $attackerData) {
            $attackerLeaderId = (int) $attackerData['leader_id'];

            // Get attacker's resources from the pre-fetched data
            $attackerResources = $allResources[$attackerLeaderId];
            $physicalAttack = $attackerResources['fighter'];
            $magicalAttack = $attackerResources['wizard'];

            $damageResults[$attackerLeaderId] = [
                'player_id' => $attackerId,
                'physical_attack' => $physicalAttack,
                'magical_attack' => $magicalAttack,
                'defenders' => []
            ];


            $defenders = Players::getNextPlayersInOrder($game, $attackerId);
            $order = 0;
            // Calculate damage against each defender
            foreach ($defenders as $defenderId => $defenderData) {
                $defenderLeaderId = (int) $defenderData['leader_id'];

                // Skip if attacker and defender are the same
                if ($attackerLeaderId === $defenderLeaderId) {
                    continue;
                }

                // Get defender's resources from the pre-fetched data
                $defenderResources = $allResources[$defenderLeaderId];
                $physicalDefense = $defenderResources['shield'];
                $magicalDefense = $defenderResources['barrier'];

                // Calculate damage
                $physicalDamage = max(0, $physicalAttack - $physicalDefense);
                $magicalDamage = max(0, $magicalAttack - $magicalDefense);
                $totalDamage = $physicalDamage + $magicalDamage;

                $damageResults[$attackerLeaderId]['defenders'][$defenderLeaderId] = [
                    'order' => $order++,
                    'player_id' => $defenderId,
                    'physical_damage' => $physicalDamage,
                    'magical_damage' => $magicalDamage,
                    'total_damage' => $totalDamage
                ];
            }
        }

        return $damageResults;
    }

    public static function executeGameState(Game $game): void
    {
        $game->trace("Executing AtkPhase state");

        $damageResults = self::calculateDamageForAllLeaders($game);

        $orderedPlayers = Players::getRemainingPlayersInOrder($game);

        // Get eliminated players to keep applying damage
        $eliminatedPlayers = Players::getEliminatedPlayers($game);

        // Execute attacks in order
        foreach ($orderedPlayers as $attackerId => $attackerData) {
            $attackerLeaderId = (int) $attackerData['leader_id'];
            $attackerName = $game->getPlayerNameById($attackerId);

            if (!isset($damageResults[$attackerLeaderId])) {
                continue;
            }

            $physicalAttack = $damageResults[$attackerLeaderId]['physical_attack'];
            $magicalAttack = $damageResults[$attackerLeaderId]['magical_attack'];

            $attackResults = [];

            // Apply damage to each defender
            foreach ($damageResults[$attackerLeaderId]['defenders'] as $defenderLeaderId => $defenderData) {
                $defenderId = $defenderData['player_id'];
                $defenderName = $game->getPlayerNameById($defenderId);

                // Get current health
                $currentHealth = $game->getUniqueValueFromDB(
                    "SELECT health FROM resources WHERE leader_id = $defenderLeaderId"
                );

                // Calculate new health
                $totalDamage = $defenderData['total_damage'];
                $newHealth = $currentHealth - $totalDamage;

                // Update health in database
                $game->DbQuery("UPDATE resources SET health = $newHealth WHERE leader_id = $defenderLeaderId");

                $relativeOrder = $defenderData['order'];

                // Record attack result
                $attackResults[$relativeOrder] = [
                    'leader_id' => $defenderLeaderId,
                    'defender_id' => $defenderId,
                    'defender_name' => $defenderName,
                    'physical_damage' => $defenderData['physical_damage'],
                    'magical_damage' => $defenderData['magical_damage'],
                    'total_damage' => $totalDamage,
                    'new_health' => $newHealth
                ];
            }

            // Apply damage to eliminated players
            foreach ($eliminatedPlayers as $eliminatedPlayerId => $eliminatedPlayerData) {
                $eliminatedLeaderId = (int) $eliminatedPlayerData['leader_id'];

                $currentHealth = $game->getUniqueValueFromDB(
                    "SELECT health FROM resources WHERE leader_id = $eliminatedLeaderId"
                );

                $newHealth = $currentHealth - $physicalAttack - $magicalAttack;

                $game->DbQuery("UPDATE resources SET health = $newHealth WHERE leader_id = $eliminatedLeaderId");
                $game->DbQuery("UPDATE player SET player_score = $newHealth WHERE player_id = $eliminatedPlayerId");
            }



            // Notify all players about the attack results
            $game->notifyAllPlayers("attackExecuted", clienttranslate('${player_name} attacks all other players ${attack_results_formatted}'), [
                'leader_id' => $attackerLeaderId,
                'player_name' => $attackerName,
                'player_id' => $attackerId,
                'physical_attack' => $physicalAttack,
                'magical_attack' => $magicalAttack,
                'attack_results' => $attackResults
            ]);
        }
        

        // Move to healing phase
        $game->gamestate->nextState("atkPhaseEnded");
    }
}
